static import { cities } from "../cities.js";

static function filterCities(query) {
  return cities.filter(city =>
    city.toLowerCase().includes(query.toLowerCase())
  );
}

<let/searchQuery=""/>

<input
  id="q"
  type="text"
  placeholder="Search cities..."
  on-input(event) {
    searchQuery = event.target.value;
  }
/>

<ul id="results">
  <for|city| of=filterCities(searchQuery)>
    <li>${city}</li>
  </for>
</ul>

<div id="count">${filterCities(searchQuery).length} matches</div>

export default async (context, next) => {
  const url = new URL(context.request.url);
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    return new Response('unauthorized', {
      status: 401,
      headers: { 'content-type': 'text/plain' }
    });
  }

  return next();
};

export default async function middleware(input, next) {
  const url = new URL(input.request.url, 'http://localhost');
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    input.response.statusCode = 401;
    input.response.setHeader('content-type', 'text/plain');
    input.response.end('unauthorized');
    return;
  }

  return await next();
}

export async function onRequest(context) {
  const url = new URL(context.request.url);
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    return new Response('unauthorized', { status: 401 });
  }
}

export async function onRequest({ request }, next) {
  const url = new URL(request.url);
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    return new Response('unauthorized', { status: 401 });
  }

  return next();
}

